  "osd-play-btn", "osd-play-icon", "osd-forward-btn", "osd-subtitles-btn",
  "osd-subtitles-label", "osd-server-btn"
];

console.log("Total required elements:", required.length);
let missing = 0;
for (const id of required) {
  const re = new RegExp(`id=["\x27]${id}["\x27]`);
  if (!re.test(html)) {
    console.error(`MISSING: ${id}`);
    missing++;
  }
}
if (missing === 0) {
  console.log("ALL 38 PLAYER OSD ELEMENTS INTACT!");
} else {
  console.error(`${missing} ELEMENTS MISSING!`);
  process.exit(1);
}

// Also check <video id="main-video-player"> tag specifically
const videoMatch = html.match(/<video[^>]*id=["\x27]main-video-player["\x27][^>]*>/);
if (videoMatch) {
  console.log("HTML5 <video id=\"main-video-player\"> tag:", videoMatch[0]);
} else {
  console.error("HTML5 video tag missing or invalid!");
  process.exit(1);
}
'

